from collections import Counter

def transform(grid):
    a=[row[:] for row in grid]
    h,w=len(a),len(a[0])
    bg=Counter(x for row in a for x in row).most_common(1)[0][0]
    # The sparse line markers are the non-background color(s); gaps of background
    # between aligned markers are recolored 2, when the gap is short.
    for color in set(x for row in a for x in row if x!=bg):
        for r in range(h):
            c=0
            while c<w:
                if a[r][c]==color:
                    j=c+1
                    while j<w and a[r][j]!=color: j+=1
                    if j<w and j-c-1<=3 and all(a[r][k]==bg for k in range(c+1,j)):
                        for k in range(c+1,j): a[r][k]=2
                    c=j
                else: c+=1
        for c in range(w):
            r=0
            while r<h:
                if a[r][c]==color:
                    j=r+1
                    while j<h and a[j][c]!=color: j+=1
                    if j<h and j-r-1<=3 and all(a[k][c]==bg for k in range(r+1,j)):
                        for k in range(r+1,j): a[k][c]=2
                    r=j
                else: r+=1
    return a

